import{_ as t,c as a,o as s,ag as l}from"./chunks/framework.DPDPlp3K.js";const g=JSON.parse('{"title":"使用 api.ipify.org 和 ipinfo.io 获取 IP 及归属地信息","description":"","frontmatter":{},"headers":[],"relativePath":"newnotion/命令行快捷公网ip查询/1.md","filePath":"newnotion/命令行快捷公网ip查询/1.md"}'),o={name:"newnotion/命令行快捷公网ip查询/1.md"};function e(n,i,p,r,d,c){return s(),a("div",null,i[0]||(i[0]=[l('<h1 id="使用-api-ipify-org-和-ipinfo-io-获取-ip-及归属地信息" tabindex="-1">使用 <code>api.ipify.org</code> 和 <code>ipinfo.io</code> 获取 IP 及归属地信息 <a class="header-anchor" href="#使用-api-ipify-org-和-ipinfo-io-获取-ip-及归属地信息" aria-label="Permalink to &quot;使用 `api.ipify.org` 和 `ipinfo.io` 获取 IP 及归属地信息&quot;">​</a></h1><p>在日常开发和运维中，获取自己的公网 IP 以及查询某个 IP 的归属地信息，是非常高频的需求。<code>api.ipify.org</code> 和 <code>ipinfo.io</code> 是两个最常用的免费 API 工具，但它们的定位和使用场景完全不同。</p><h2 id="api-ipify-org-简洁的-ip-查询工具" tabindex="-1"><code>api.ipify.org</code>：简洁的 IP 查询工具 <a class="header-anchor" href="#api-ipify-org-简洁的-ip-查询工具" aria-label="Permalink to &quot;`api.ipify.org`：简洁的 IP 查询工具&quot;">​</a></h2><p><code>api.ipify.org</code> 是一个专注于一件事的 API：<strong>返回你的公网 IP 地址</strong>。</p><ul><li><strong>支持 IPv4 和 IPv6</strong>：默认返回 IPv4，可通过 <code>?format=json</code> 获取 JSON 格式。</li><li><strong>支持 HTTPS</strong>：通过 <code>https://api.ipify.org</code> 访问，保证传输安全。</li><li><strong>极简响应</strong>：默认只返回纯文本的 IP 地址，适合脚本处理。</li><li><strong>无请求限制</strong>：个人项目无需注册即可免费使用。</li></ul><h3 id="api-ipify-org-用法" tabindex="-1"><code>api.ipify.org</code> 用法 <a class="header-anchor" href="#api-ipify-org-用法" aria-label="Permalink to &quot;`api.ipify.org` 用法&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#9CA0B0;--shiki-light-font-style:italic;--shiki-dark:#6C7086;--shiki-dark-font-style:italic;"># 返回纯文本 IPv4</span></span>\n<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">curl</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> api.ipify.org</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#9CA0B0;--shiki-light-font-style:italic;--shiki-dark:#6C7086;--shiki-dark-font-style:italic;"># 返回 JSON 格式</span></span>\n<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">curl</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> api.ipify.org?format=json</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#9CA0B0;--shiki-light-font-style:italic;--shiki-dark:#6C7086;--shiki-dark-font-style:italic;"># 返回 IPv6</span></span>\n<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">curl</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -6</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> api.ipify.org</span></span></code></pre></div><h3 id="api-ipify-org-适用场景" tabindex="-1"><code>api.ipify.org</code> 适用场景 <a class="header-anchor" href="#api-ipify-org-适用场景" aria-label="Permalink to &quot;`api.ipify.org` 适用场景&quot;">​</a></h3><ul><li><strong>脚本中获取本机公网 IP</strong>：如动态 DNS 更新脚本。</li><li><strong>网络调试</strong>：快速确认出口 IP 是否变化。</li><li><strong>容器/服务器初始化</strong>：获取当前节点的公网地址。</li></ul><h2 id="ipinfo-io-丰富的-ip-情报查询工具" tabindex="-1"><code>ipinfo.io</code>：丰富的 IP 情报查询工具 <a class="header-anchor" href="#ipinfo-io-丰富的-ip-情报查询工具" aria-label="Permalink to &quot;`ipinfo.io`：丰富的 IP 情报查询工具&quot;">​</a></h2><p><code>ipinfo.io</code> 不仅返回 IP，还提供归属地、运营商、时区、地理位置等丰富信息。</p><ul><li><strong>免费版无需注册</strong>：每天有约 50,000 次请求限制，个人使用绰绰有余。</li><li><strong>支持查询任意 IP</strong>：只需在 URL 后拼接 IP 地址。</li><li><strong>返回结构化 JSON</strong>：包含 <code>ip</code>、<code>city</code>、<code>region</code>、<code>country</code>、<code>loc</code>、<code>org</code>、<code>postal</code>、<code>timezone</code> 等字段。</li><li><strong>支持批量查询</strong>：可通过 <code>POST /batch</code> 接口一次性查询多个 IP。</li><li><strong>提供 CLI 工具</strong>：官方提供 <code>ipinfo-cli</code> 命令行客户端，方便高频使用。</li></ul><h3 id="ipinfo-io-用法" tabindex="-1"><code>ipinfo.io</code> 用法 <a class="header-anchor" href="#ipinfo-io-用法" aria-label="Permalink to &quot;`ipinfo.io` 用法&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#9CA0B0;--shiki-light-font-style:italic;--shiki-dark:#6C7086;--shiki-dark-font-style:italic;"># 查询本机 IP 归属地（JSON 格式）</span></span>\n<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">curl</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> ipinfo.io</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#9CA0B0;--shiki-light-font-style:italic;--shiki-dark:#6C7086;--shiki-dark-font-style:italic;"># 查询任意 IP 归属地</span></span>\n<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">curl</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> ipinfo.io/103.242.73.138</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#9CA0B0;--shiki-light-font-style:italic;--shiki-dark:#6C7086;--shiki-dark-font-style:italic;"># 只返回特定字段</span></span>\n<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">curl</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> ipinfo.io/103.242.73.138/city</span></span></code></pre></div><h3 id="ipinfo-io-适用场景" tabindex="-1"><code>ipinfo.io</code> 适用场景 <a class="header-anchor" href="#ipinfo-io-适用场景" aria-label="Permalink to &quot;`ipinfo.io` 适用场景&quot;">​</a></h3><ul><li><strong>日志分析</strong>：追溯访问者来源地、运营商信息。</li><li><strong>用户画像</strong>：根据 IP 归属地为用户展示本地化内容。</li><li><strong>网络安全</strong>：初步判断访问 IP 是否来自异常地区。</li><li><strong>运维监控</strong>：了解出口 IP 的归属和网络链路信息。</li></ul><h2 id="两者对比总览" tabindex="-1">两者对比总览 <a class="header-anchor" href="#两者对比总览" aria-label="Permalink to &quot;两者对比总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">功能</th><th style="text-align:left;"><code>api.ipify.org</code></th><th style="text-align:left;"><code>ipinfo.io</code></th></tr></thead><tbody><tr><td style="text-align:left;"><strong>响应内容</strong></td><td style="text-align:left;">仅返回 IP 地址</td><td style="text-align:left;">返回完整归属地信息</td></tr><tr><td style="text-align:left;"><strong>查询任意 IP</strong></td><td style="text-align:left;">不支持，只能查自己</td><td style="text-align:left;">支持</td></tr><tr><td style="text-align:left;"><strong>数据格式</strong></td><td style="text-align:left;">纯文本或 JSON</td><td style="text-align:left;">结构化 JSON</td></tr><tr><td style="text-align:left;"><strong>请求限制</strong></td><td style="text-align:left;">无（GCP 免费层）</td><td style="text-align:left;">约 5 万次/天（免费版）</td></tr><tr><td style="text-align:left;"><strong>适用场景</strong></td><td style="text-align:left;">获取本机 IP</td><td style="text-align:left;">查询 IP 归属地</td></tr></tbody></table><h2 id="真实场景-两者结合使用" tabindex="-1">真实场景：两者结合使用 <a class="header-anchor" href="#真实场景-两者结合使用" aria-label="Permalink to &quot;真实场景：两者结合使用&quot;">​</a></h2><p>在实际使用中，两者常常<strong>配合使用</strong>。</p><p>你刚才的执行过程正好体现了这种配合：</p><ol><li>用 <code>curl -4 https://api.ipify.org</code> 获取自己的公网 IP。</li><li>拿到 IP 后，再用 <code>curl ipinfo.io/&lt;IP&gt;</code> 查询这个 IP 的归属地信息。</li></ol><p>这种组合方式适合**需要同时知道“自己是谁”和“自己在哪”**的场景，比如在分布式系统的调试、代理出口检测、日志溯源等工作中非常实用。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ol><li><strong>仅公网 IP 可查</strong>：内网 IP（如 <code>192.168.*.*</code>）在 <code>ipinfo.io</code> 上查不到归属地。</li><li><strong>IP 归属地的精度</strong>：IP 地理信息通常是<strong>城市级别</strong>，无法精确到街道或具体建筑。</li><li><strong>数据可能有延迟</strong>：IP 段重新分配后，归属数据库可能需要数周才能更新。</li></ol><p>如果你的需求只是“想看看自己出口 IP 是多少，偶尔查查归属地”，这两个工具的组合方案已经足够稳定且免费。如果需要更频繁的批量查询，可以考虑 <code>ipinfo</code> 的付费方案或使用离线数据库（如 <code>nali</code>）。</p>',26)]))}const f=t(o,[["render",e]]);export{g as __pageData,f as default};
